    # ── SM-07: родное отверстие. Действие `edit` ИЗМЕРЯЕМО и проверяется СВОИМ режимом ──────────
    def mk_hole(mode, diameter, depth, tag, offset=None, counterbore=None, countersink=None):
        def build(doc, rev):
            rev, body, _ref, code = mk_plate(doc, rev, tag)
            if code:
                return None, rev, "пластина: " + str(code)
            top = top_face(doc, body)
            if not top:
                return None, rev, "верхняя грань z=10 не найдена по нормали и площади"
            args = {"face_ref": top, "expected_revision": rev, "mode": mode,
                    "diameter_mm": diameter}
            if depth is not None:
                args["depth_mm"] = depth
            if counterbore:
                args["counterbore_diameter_mm"], args["counterbore_depth_mm"] = counterbore
            if countersink:
                args["countersink_diameter_mm"], args["countersink_angle_deg"] = countersink
            if offset:
                args["offset_x_mm"], args["offset_y_mm"] = offset
            env, code = call("kompas_hole", args)
            rev = (env or {}).get("revision_after") or rev
            # Ссылка берётся из ОТВЕТА создания и служит только подтверждением, что признак создан:
            # адресация идёт по ИМЕНИ строки дерева (см. own_row) — ссылка из ответа к следующему
            # вызову мертва, реестр выдаёт её против ревизии (STALE_REFERENCE, измерено на B4).
            return (result(env).get("feature_ref") or {}).get("id"), rev, code
        return build

    def cs_extra(pilot, mouth, angle_deg):
        """Снятое зенковкой СВЕРХ пилота: π·h/3·(rM² + rP·rM − 2·rP²), h = (rM − rP)/tan(угол/2).

        Та же аналитика, что в §9.2 SOL-HOLE и в таблице M.3 из 11 строк; h ПРОИЗВОДНА от угла и
        устья, поэтому здесь она считается, а не задаётся.
        """
        r_m, r_p = mouth / 2.0, pilot / 2.0
        h = (r_m - r_p) / math.tan(math.radians(angle_deg / 2.0))
        return math.pi * h / 3.0 * (r_m ** 2 + r_p * r_m - 2.0 * r_p ** 2)

    def hole_negatives(mode):
        """Отказы создания и ПРАВКИ. Ни один случай не трогает модель — иначе драйвер, сверяющий
        состояние до и после всего блока, отказывал бы прибору, а не продукту.

        Отказы правки добавлены нарядом SM07 §3.4 и стоят здесь, а не отдельной строкой: матрица
        строки SM-07 объявляет действие `negative_tests` один раз, и «чужие поля правки отвергаются»
        — это его часть. Все три отказывают ДО COM, поэтому модель после блока не меняется.
        """
        def run(doc, rev, own_name):
            out = []
            top = top_face(doc, body_at(doc, (-50.0, -40.0, 0.0), (50.0, 40.0, 10.0)))
            for label, payload, want in (
                    ("диаметр 0", {"mode": "blind_flat", "diameter_mm": 0.0, "depth_mm": 6.0},
                     "INVALID_ARGUMENT"),
                    ("глубина отрицательная",
                     {"mode": "blind_flat", "diameter_mm": 10.0, "depth_mm": -6.0},
                     "INVALID_ARGUMENT"),
                    ("цековка меньше пилота",
                     {"mode": "through_counterbore", "diameter_mm": 10.0,
                      "counterbore_diameter_mm": 8.0, "counterbore_depth_mm": 4.0},
                     "INVALID_ARGUMENT")):
                payload = dict(payload, face_ref=top, expected_revision=ctx(doc))
                env, code = call("kompas_hole", payload)
                out.append({"case": label, "expected": want, "got": code, "ok": code == want,
                            "message": describe(env)})

            href = (own_row(doc, own_name) or {}).get("ref")
            # Поле ЧУЖОГО РЕЖИМА выбирается по режиму самой строки: у цековки чужим будет поле
            # зенковки, у зенковки — поле цековки, у глухого — любое из них. Одно и то же поле для
            # всех строк было бы то «чужим», то «своим», и проверка ничего не утверждала бы.
            foreign_field, foreign_value = {
                "blind_flat": ("counterbore_diameter_mm", 20.0),
                "through_counterbore": ("countersink_diameter_mm", 24.0),
                "through_countersink": ("counterbore_diameter_mm", 20.0),
            }[mode]
            for label, payload, want in (
                    ("правка: поле ЧУЖОГО режима",
                     {foreign_field: foreign_value}, "INVALID_ARGUMENT"),
                    ("правка: поле чужого семейства", {"radius_mm": 3.0}, "INVALID_ARGUMENT"),
                    ("правка: нулевой диаметр", {"diameter_mm": 0.0}, "INVALID_ARGUMENT")):
                env, code = call("kompas_update_feature",
                                 dict(payload, feature_ref=href, expected_revision=ctx(doc)))
                out.append({"case": label, "expected": want, "got": code, "ok": code == want,
                            "message": describe(env)})
            return out
        return run

    def hole_edit(payload):
        def run(doc, rev, fref):
            env, code = call("kompas_update_feature",
                             dict(payload, feature_ref=fref, expected_revision=ctx(doc)))
            return rev, code
        return run

    def hole_edit_check(nn, mode, payload, expect_removed, expect_delta, expect_center):
        """Правка отверстия: различающая пара объёмов, чтение обратно, save → close → reopen.

        Возвращается ТРЕТЬИМ значением id ПЕРЕОТКРЫТОГО документа: действие `edit` обязано
        доказать, что правка пережила запись и переоткрытие, а это можно сделать только закрыв
        документ. Драйвер продолжает строку по переоткрытому документу (см. разбор трёх значений
        в самом драйвере).

        ЧТО ИМЕННО РАЗЛИЧАЕТ. Объём — и АБСОЛЮТНЫЙ (после правки), и ДЕЛЬТА (снято правкой): первый
        ловит «правка не применилась», вторая — «применилось не то». Положение оси читается там, где
        строка объявлена позиционной: сместившееся к началу координат отверстие дало бы тот же
        объём, и строка прошла бы ЛОЖНО.
        """
        want_type = {"blind_flat": "ksHTBase", "through_counterbore": "ksHTCounterbore",
                     "through_countersink": "ksHTCountersinking"}[mode]

        def hole_ref(d):
            row = next((r for r in tree_rows(d) if r["type"] == "583"), None)
            return (row or {}).get("ref")

        def read_hole(d):
            # `read_feature` этой группы возвращает УЖЕ результат (`result(env)`), а не конверт: в
            # зонде §3.1 та же по имени функция возвращала конверт, и перенос строки оттуда дал
            # чтение `.get("result")` у результата — то есть пустой словарь. Дефект ПРИБОРА, а не
            # факт о продукте: он выглядел как «параметры не перечитались» на строке F08.17.edit,
            # где объём и дельта уже сошлись с аналитикой. Сверка идёт с ключом `hole` результата.
            return (read_feature(hole_ref(d)) or {}).get("hole") or {}

        def compare(hole):
            bad = []
            if hole.get("hole_type") != want_type:
                bad.append(f"hole_type={hole.get('hole_type')} (ожидание {want_type})")
            for field in ("diameter_mm", "depth_mm", "counterbore_diameter_mm",
                          "counterbore_depth_mm", "countersink_diameter_mm",
                          "countersink_angle_deg"):
                if field in payload and not near(hole.get(field), payload[field]):
                    bad.append(f"{field}={hole.get(field)} (ожидание {payload[field]})")
            return (not bad), ", ".join(
                f"{k}={hole.get(k)}" for k in ("hole_type", "diameter_mm", "depth_mm",
                                               "counterbore_diameter_mm", "counterbore_depth_mm",
                                               "countersink_diameter_mm", "countersink_angle_deg",
                                               "countersink_depth_mm")), bad

        def check(before, after, doc):
            notes = []
            vol_before = before["volumes"][0] if before["volumes"] else None
            vol_after = after["volumes"][0] if after["volumes"] else None
            removed = None if None in (vol_before, vol_after) else vol_before - vol_after
            want_volume = plate - expect_removed
            vol_ok = vol_after is not None and near(vol_after, want_volume)
            delta_ok = removed is not None and near(removed, expect_delta)
            notes.append(f"объём после правки {vol_after} (ожидание {want_volume:.9f})={vol_ok}; "
                         f"снято правкой {removed} (ожидание {expect_delta:.9f})={delta_ok}")

            ok1, txt1, bad1 = compare(read_hole(doc))
            notes.append(f"чтение обратно по свежей ссылке из дерева: {txt1}"
                         + (f"; РАСХОЖДЕНИЯ: {', '.join(bad1)}" if bad1 else ""))

            path = os.path.join(workdir, "f08-%02d-edit-%s.m3d" % (nn, uuid.uuid4().hex[:8]))
            _e, s_env, _r = client.tool("kompas_save_document", {
                "document_id": doc, "target_path": path,
                "expected_revision": ctx(doc), "operation_id": str(uuid.uuid4())}, timeout=240)
            save_code = error_code(s_env)
            close(doc)
            _e, o_env, _r = client.tool("kompas_open_document", {
                "application_id": app_id, "path": path, "access": "edit",
                "operation_id": str(uuid.uuid4())}, timeout=240)
            doc2 = result(o_env).get("document_id") or result(o_env).get("id")
            if not doc2:
                return False, "; ".join(notes + [f"переоткрытие не удалось: err={error_code(o_env)}"]), None

            re_state = state(doc2)
            vol_re = re_state["volumes"][0] if re_state["volumes"] else None
            reopen_ok = vol_re is not None and near(vol_re, want_volume)
            hole2 = read_hole(doc2)
            ok2, txt2, bad2 = compare(hole2)
            center_ok = True
            if expect_center:
                c = hole2.get("center_mm") or []
                center_ok = (len(c) >= 2 and abs(c[0] - expect_center[0]) <= 0.5
                             and abs(c[1] - expect_center[1]) <= 0.5)
                notes.append(f"положение оси после переоткрытия: {list(c[:2])} "
                             f"(ожидание {list(expect_center)})={center_ok}")
            notes.append(f"после переоткрытия: файл={os.path.exists(path)} объём={vol_re} "
                         f"(ожидание {want_volume:.9f})={reopen_ok}; чтение: {txt2}"
                         + (f"; РАСХОЖДЕНИЯ: {', '.join(bad2)}" if bad2 else ""))
            ok = (vol_ok and delta_ok and ok1 and save_code is None and reopen_ok and ok2 and center_ok)
            return ok, "; ".join(notes), doc2
        return check

    hole_specs = (
        (15, "SM-07.native_hole.blind_flat_bottom", "blind_flat", 6.0, None,
         hole_read("blind_flat", 10.0, 6.0)),
        (16, "SM-07.native_hole.through_cylindrical", "blind_flat", 10.0, None,
         hole_read("blind_flat", 10.0, 10.0)),
        (17, "SM-07.native_hole.through_counterbore", "through_counterbore", None, None,
         hole_read("through_counterbore", 10.0)),
        (18, "SM-07.native_hole.through_countersink", "through_countersink", None, None,
         hole_read("through_countersink", 10.0)),
        (19, "SM-07.native_hole.axis_by_face_normal", "blind_flat", 6.0, None,
         hole_read("blind_flat", 10.0, 6.0)),
        (20, "SM-07.native_hole.position_off_origin", "blind_flat", 6.0, (25.0, 15.0),
         hole_read("blind_flat", 10.0, 6.0, center=(25.0, 15.0))),
    )
    hole_removed_by_row = {
        "SM-07.native_hole.blind_flat_bottom": hole_removed["blind6"],
        "SM-07.native_hole.through_cylindrical": hole_removed["through"],
        "SM-07.native_hole.through_counterbore": hole_removed["counterbore"],
        "SM-07.native_hole.through_countersink": hole_removed["countersink"],
        "SM-07.native_hole.axis_by_face_normal": hole_removed["blind6"],
        "SM-07.native_hole.position_off_origin": hole_removed["blind6"],
    }
    # Правка КАЖДОЙ строки — правка СВОЕГО режима, и КАЖДАЯ ИЗМЕРЕНА отдельной постановкой зонда
    # scratch/_hole_edit_probe.py (шаг M.6, отчёт docs/acceptance/api7/hole-modes.md):
    #   глухое Ø10 6 → 8            Δ 157.079632679 = π·r²·2
    #   сквозное Ø10 → Ø12          Δ 345.575191895 = π·(36−25)·10
    #   выточка Ø18×4 → Ø20×5       Δ 474.380490692 = кольца π/4·(D²−d²)·h
    #   устье Ø20 → Ø24 при 90°     Δ 605.280184592 = π·h/3·(rM²+rP·rM−2rP²), h производна
    #   то же в точке (25, 15)      Δ 157.079632679 + положение оси обязано сохраниться
    # Ожидания объявлены ЗДЕСЬ и до вызова, а не взяты из ответов сервера.
    hole_edits = {
        15: ({"diameter_mm": 10.0, "depth_mm": 8.0},
             math.pi * 25.0 * 8.0, math.pi * 25.0 * 2.0, None),
        # У сквозного цилиндрического меняется ДИАМЕТР, а не глубина: глубина у сквозного инертна, и
        # объёмом такая правка не различалась бы вовсе — строка прошла бы на «не применилось».
        16: ({"diameter_mm": 12.0, "depth_mm": 10.0},
             math.pi * 36.0 * 10.0, math.pi * 11.0 * 10.0, None),
        17: ({"diameter_mm": 10.0, "counterbore_diameter_mm": 20.0, "counterbore_depth_mm": 5.0},
             hole_removed["through"] + math.pi / 4.0 * (20.0 ** 2 - 10.0 ** 2) * 5.0,
             math.pi / 4.0 * (20.0 ** 2 - 10.0 ** 2) * 5.0
             - math.pi / 4.0 * (18.0 ** 2 - 10.0 ** 2) * 4.0, None),
        18: ({"diameter_mm": 10.0, "countersink_diameter_mm": 24.0, "countersink_angle_deg": 90.0},
             hole_removed["through"] + cs_extra(10.0, 24.0, 90.0),
             cs_extra(10.0, 24.0, 90.0) - cs_extra(10.0, 20.0, 90.0), None),
        19: ({"diameter_mm": 10.0, "depth_mm": 8.0},
             math.pi * 25.0 * 8.0, math.pi * 25.0 * 2.0, None),
        20: ({"diameter_mm": 10.0, "depth_mm": 8.0},
             math.pi * 25.0 * 8.0, math.pi * 25.0 * 2.0, (25.0, 15.0)),
    }
    for nn, row, mode, depth, offset, reader in hole_specs:
        removed = hole_removed_by_row[row]
        kw = {}
        if mode == "through_counterbore":
            kw["counterbore"] = (18.0, 4.0)
        if mode == "through_countersink":
            kw["countersink"] = (20.0, 90.0)
        payload, edit_removed, edit_delta, edit_center = hole_edits[nn]
        specs.append({
            "nn": nn, "row": row, "types": {"583"},
            "make": mk_hole(mode, 10.0, depth, "F08%02d" % nn, offset=offset, **kw),
            "edit": hole_edit(payload),
            "edit_check": hole_edit_check(nn, mode, payload, edit_removed, edit_delta, edit_center),
            "created": plate_state(plate - removed),
            "edited": plate_state(plate - edit_removed),
            # Восстановление возвращает состояние ПОСЛЕ правки, а не состояние создания: до
            # появления правки эти два совпадали, и ожидание было бы унаследовано неверно.
            "suppressed": plate_state(plate), "restored": plate_state(plate - edit_removed),
            "deleted": plate_state(plate),
            "read_expect": reader,
            "negatives": hole_negatives(mode),
            "note": f"режим {mode}: снято {removed:.6f} (аналитика §9.2 SOL-HOLE); правка сняла "
                    f"ещё {edit_delta:.9f} → {edit_removed:.9f} (измерено зондом §3.1, шаг M.6)",
        })

    # ── SM-09: скругление ─────────────────────────────────────────────────────────────────────
    def mk_fillet(radius, tag, n_edges=4):
        def build(doc, rev):
            rev, body, _ref, code = mk_plate(doc, rev, tag)
            if code:
                return None, rev, "пластина: " + str(code)
            erefs = corner_edges(doc, body)
            if len(erefs) != 4:
                return None, rev, f"угловых рёбер {len(erefs)}, ожидалось 4"
            env, code = call("kompas_fillet", {
                "edge_refs": erefs, "radius_mm": radius, "expected_revision": rev})
            rev = (env or {}).get("revision_after") or rev
            ref = (result(env).get("feature_ref") or {}).get("id")
            return ref, rev, code
        return build

    def ed_fillet(radius):
        def run(doc, rev, fref):
            env, code = call("kompas_update_feature", {
                "feature_ref": fref, "expected_revision": ctx(doc), "radius_mm": radius})
            return rev, code
        return run

    def fillet_negatives(doc, rev, own_name):
        """Отказы скругления НА УЖЕ ПОСТРОЕННОМ теле.

        Прежняя редакция строила ВТОРУЮ пластину внутри отрицательной проверки — то есть меняла
        документ МЕЖДУ снимками «до» и «после», которыми драйвер доказывает, что отказ не тронул
        модель. Снимки тогда расходились по причине прибора, а не по причине отказа, и строка
        `negative_tests` отказывала бы сама себе. Пластина здесь уже есть: её построил `make`.
        """
        body = body_at(doc, (-50.0, -40.0, 0.0), (50.0, 40.0, 10.0))
        erefs = corner_edges(doc, body) if body else []
        out = []
        for label, payload in (("радиус 0", {"edge_refs": erefs[:1], "radius_mm": 0.0}),
                               ("пустой список рёбер", {"edge_refs": [], "radius_mm": 3.0})):
            payload = dict(payload, expected_revision=ctx(doc))
            env, code2 = call("kompas_fillet", payload)
            out.append({"case": label, "expected": "INVALID_ARGUMENT", "got": code2,
                        "ok": code2 == "INVALID_ARGUMENT", "message": describe(env)})
        return out

